package ais.common.newui.akunting;
import java.text.SimpleDateFormat;import java.util.Date;import java.util.HashSet;import java.util.Iterator;import java.util.Map;import java.util.Set;import javax.servlet.http.HttpServletRequest;import javax.servlet.http.HttpServletResponse;import org.json.JSONArray;import org.json.JSONObject;import ais.action.master.sekolah.util.SekolahUtil;import ais.common.Common;import ais.common.newui.NewUiRouteGuard;import ais.common.newui.akunting.NewUiStandingInstructionService.Row;import ais.common.newui.akunting.NewUiStandingInstructionService.Snapshot;import ais.database.model.Tbmuser;import ais.database.model.rab.SatuanKerja;
public final class NewUiStandingInstructionController{private static final String M="akunting",P="standing_instruction";private NewUiStandingInstructionController(){}public static void handle(HttpServletRequest q,HttpServletResponse r)throws Exception{r.setContentType("application/json; charset=UTF-8");r.setHeader("Cache-Control","no-store");JSONObject j=new JSONObject();try{String a=text(q.getParameter("action"),"list");if(!NewUiRouteGuard.isActionAuthorized(q,M,P,"save_note".equals(a)?"update":"list")){r.setStatus(403);fail(j,"ACTION_FORBIDDEN","Hak akses tidak tersedia.");write(r,j);return;}Set<SatuanKerja>units=SekolahUtil.ambilSatuanKerjas();Tbmuser user=Common.getCurrentUser(q);NewUiStandingInstructionService s=new NewUiStandingInstructionService();if("save_note".equals(a)){if(!"POST".equalsIgnoreCase(q.getMethod())||!csrf(q)){r.setStatus(403);fail(j,"CSRF_INVALID","Token CSRF tidak valid.");write(r,j);return;}s.updateNote(id(q,"id",true),q.getParameter("note"),units,user);}else if(!"list".equals(a))throw new IllegalArgumentException("Aksi tidak dikenal.");Snapshot d=s.load(q.getParameter("q"),date(q,"start"),date(q,"end"),id(q,"unitId",false),bool(q,"pending"),bool(q,"approved"),bool(q,"transferred"),integer(q,"page",0),Math.min(100,Math.max(10,integer(q,"size",20))),units);encode(j,d,units);j.put("ok",true);}catch(IllegalArgumentException e){r.setStatus(422);fail(j,"VALIDATION_FAILED",e.getMessage());}catch(Exception e){r.setStatus(500);fail(j,"INTERNAL_ERROR","Gagal memuat standing instruction.");try{ais.common.ErrorAuditUtil.record(e,"NewUiStandingInstructionController");}catch(Exception ignored){}}write(r,j);}private static void encode(JSONObject j,Snapshot d,Set<SatuanKerja>u)throws Exception{JSONArray a=new JSONArray();for(Row x:d.rows)a.put(new JSONObject().put("id",x.id).put("code",x.code).put("name",x.name).put("note",x.note).put("time",x.time==null?JSONObject.NULL:x.time.getTime()).put("amount",x.amount).put("account",x.account).put("bank",x.bank).put("accountName",x.accountName).put("accountNumber",x.accountNumber).put("unit",x.unit).put("status",x.status).put("transfer",x.transfer).put("sopId",x.sopId).put("payroll",x.payroll));JSONArray units=new JSONArray();for(SatuanKerja x:u)units.put(new JSONObject().put("id",x.getId()).put("label",x.getNama()));j.put("rows",a).put("units",units).put("total",d.total).put("status",map(d.status)).put("types",map(d.types));}private static JSONObject map(Map<String,Integer>m)throws Exception{JSONObject j=new JSONObject();for(Map.Entry<String,Integer>e:m.entrySet())j.put(e.getKey(),e.getValue());return j;}private static boolean csrf(HttpServletRequest q){Object e=q.getSession().getAttribute("newUiCsrfToken");String v=q.getHeader("X-CSRF-Token");return e!=null&&v!=null&&String.valueOf(e).equals(v);}private static boolean bool(HttpServletRequest q,String n){return"true".equalsIgnoreCase(q.getParameter(n));}private static Long id(HttpServletRequest q,String n,boolean z){String v=q.getParameter(n);if(v==null||v.trim().length()==0){if(z)throw new IllegalArgumentException(n+" wajib diisi.");return null;}try{return Long.valueOf(v);}catch(Exception e){throw new IllegalArgumentException(n+" tidak valid.");}}private static int integer(HttpServletRequest q,String n,int f){try{return Integer.parseInt(text(q.getParameter(n),String.valueOf(f)));}catch(Exception e){return f;}}private static Date date(HttpServletRequest q,String n){String v=q.getParameter(n);if(v==null||v.length()==0)return null;try{return new SimpleDateFormat("yyyy-MM-dd").parse(v);}catch(Exception e){throw new IllegalArgumentException(n+" tidak valid.");}}private static String text(String v,String f){return v==null||v.trim().length()==0?f:v.trim();}private static void fail(JSONObject j,String c,String m)throws Exception{j.put("ok",false).put("code",c).put("message",m);}private static void write(HttpServletResponse r,JSONObject j)throws Exception{r.getWriter().write(j.toString());}}
